  const mappedCount = Object.keys(saved.mappings || {}).length;
  const requiredMissing = selectedTable.fields.filter(f => f.required && !saved.mappings?.[f.name] && !f.generated).length;
  const selectedText = state.mapper.selected ? `${state.mapper.selected.sheet}!${state.mapper.selected.cell} · ${display(state.mapper.selected.value)}` : 'Select a source cell, then choose a target field.';
  const previewRows = saved.rows?.length ? saved.rows : Object.keys(saved.preview || {}).length ? [saved.preview] : [];
  const oracleFields = [...selectedTable.fields].sort((a, b) => a.ordinal - b.ordinal);
