item.stdout:
/* Organic anchor: calm, tactile surfaces for a precise data workflow. */
:root {
  --green-50: #f1f7f3;
  --green-100: #e2efe7;
  --green-200: #c9e0d2;
  --green-300: #a8cbb8;
  --green-400: #7eb098;
  --green-500: #579477;
  --green-600: #39775d;
  --green-700: #245b47;
  --green-800: #194638;
  --green-900: #12372d;
  --ink: #18382e;
  --muted: #5c7168;
  --line: #b9cec3;
  --surface: #edf5f0;
  --canvas: #dceae2;
  --teal: var(--green-700);
  --teal-dark: var(--green-800);
  --soft: var(--green-100);
  --amber: #c08e3a;
  --red: #a55239;
  --sage: var(--green-400);
  --clay: #8cae9d;
  --terracotta: #c66b3d;
  --oat: var(--green-200);
  --shadow: 0 18px 50px rgba(18, 55, 45, .11);
  font-family: "Avenir Next", Avenir, "Segoe UI", sans-serif;
  color: var(--ink);
}

html { background: var(--canvas); }
body {
  position: relative;
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 0%, rgba(126, 176, 152, .46), transparent 30rem),
    radial-gradient(circle at 95% 18%, rgba(87, 148, 119, .25), transparent 34rem),
    linear-gradient(145deg, var(--green-50) 0%, var(--canvas) 48%, var(--green-200) 100%),
    var(--canvas);
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: .025;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

::selection { background: var(--oat); color: var(--ink); }
* { scrollbar-color: var(--sage) rgba(238, 230, 215, .72); }
button, input, select, textarea { font-family: inherit; }
button, .dropzone { transition: transform 220ms ease, background-color 220ms ease, border-color 220ms ease, box-shadow 220ms ease; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, .dropzone:focus-visible {
  outline: 3px solid rgba(96, 108, 56, .34);
  outline-offset: 3px;
}

.site-header {
  min-height: 78px;
  padding-inline: max(28px, calc((100vw - 1480px) / 2));
  background: linear-gradient(110deg, rgba(241, 247, 243, .95), rgba(226, 239, 231, .92));
  border-color: rgba(36, 91, 71, .2);
  box-shadow: 0 8px 28px rgba(18, 55, 45, .08);
