 .notice { background: #d9ece0; border-color: #9fc1ad; color: #194638; }
 footer { border-color: #b5cec0; color: #526c60; }
+.preview-kicker { display: block; margin-bottom: 8px; color: #39775d; font-size: 10px; font-weight: 700; letter-spacing: .12em; }
+.preview-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin: 0 0 22px; }
+.preview-summary > div { display: flex; flex-direction: column; gap: 5px; padding: 16px 18px; border: 1px solid #c6ded0; border-radius: 16px; background: linear-gradient(135deg, #f1f8f3, #e2efe7); }
+.preview-summary strong { color: #194638; font-size: 24px; font-weight: 600; line-height: 1; }
+.preview-summary span { color: #5c7168; font-size: 11px; }
+.preview-panel .table-preview { background: #ffffff; }
+.preview-panel .table-preview > summary { min-height: 48px; }
+.preview-panel .table-preview .table-preview { margin: 10px; border-color: #d2e3d9; }
+.preview-actions { align-items: center; padding: 22px 0 2px; }
+.preview-actions p { max-width: 620px; color: #526c60; }
+.preview-actions .button { min-width: 210px; }
+@media (max-width: 640px) { .preview-summary { grid-template-columns: 1fr; } .preview-actions .button { width: 100%; } }
*** End Patch";
text(await tools.apply_patch(patch));

